      case 17: return demo_17_flower_100mm;
      case 18: return demo_18_frame_test_150x100;
      case 19: return demo_19_gear_100mm;
      case 20: return demo_20_generated_grid_test;
      case 21: return demo_21_grid_100x80_10mm;
