/**
 * M750: Run an embedded pen plotter demo.
 *
 *  D<demo>  Demo number from the list shown by bare M750.
 */
void GcodeSuite::M750() {
  if (!parser.seenval('D')) {
    report_demo_list();
    return;
  }

  const uint8_t demo = parser.byteval('D');
  PGM_P const script = demo_script(demo);

  if (script) {
    SERIAL_ECHO_MSG("Running embedded pen plotter demo D", demo);
    queue.inject_P(script);
  }
  else
    SERIAL_ERROR_MSG("M750 D", demo, " out of range. Use D1..D", PENPLOTTER_DEMO_COUNT);
}

